/* SPDX-License-Identifier: GPL-2.0-only
 * Starbite OS cities (Track A, 8a): World Clock's and Weather's search (design-ref's Clock / Weather specs). The table
 * (tzcities.c) is generated by starbite/tools/mk-tzcities.py from GeoNames (CC BY 4.0), sorted by name; each city is
 * in one of kern/tzdb.c's zones. Pure data: the host and the phone link it as it is. */
#pragma once
#include <stdint.h>

struct tzcity {
    const char *name;               /* UTF-8, as GeoNames writes it ("Zürich") */
    uint8_t country;                /* an index into tzc_country */
    uint8_t zone;                   /* an index into tzdb[] */
    int32_t lat_e4, lon_e4;         /* degrees x 10000 (north, east positive) */
};

extern const struct tzcity tzcities[];
extern const int tzcities_n;
extern const char *const tzc_country[];
extern const int tzc_ncountry;
/* tzcity.c: the cities whose name, or a word in it, starts with query (case and Latin accents ignored), in the
 * table's order; out gets up to max indexes; returns how many */
int tzc_find(const char *query, int *out, int max);
